import { createGuardrails, generateSecret, verifySync } from "otplib";

// Every secret in admin_two_factor_secrets was generated by otplib 12, whose default is
// 10 random bytes (16 base32 characters). otplib 13 rejects secrets shorter than the
// RFC 4226 recommendation of 16 bytes, so the minimum is lowered to 10 bytes here to keep
// existing authenticator apps working. New secrets keep the same 10-byte size so the
// setup screen and QR code stay exactly as they were.
const LEGACY_SECRET_BYTES = 10;
const guardrails = createGuardrails({ MIN_SECRET_BYTES: LEGACY_SECRET_BYTES });

/** New base32 TOTP secret for an admin user (stored as-is in admin_two_factor_secrets). */
export const generateTotpSecret = (): string => generateSecret({ length: LEGACY_SECRET_BYTES });

/**
 * True when `token` is the code for the current 30-second step of `secret`
 * (SHA-1, 6 digits, no drift window — the otplib 12 authenticator defaults).
 * Malformed tokens or secrets are reported as invalid instead of throwing.
 */
export const verifyTotp = (token: string, secret: string): boolean => {
  try {
    return verifySync({ secret, token, guardrails, epochTolerance: 0 }).valid;
  } catch {
    return false;
  }
};

/**
 * otpauth:// URI that authenticator apps scan from the setup QR code. Built by hand in the
 * exact format otplib 12's `keyuri` produced (otplib 13 omits the default parameters), so
 * the QR code shown during 2FA setup does not change.
 */
export const totpKeyUri = (accountName: string, issuer: string, secret: string): string => {
  const label = `${encodeURIComponent(issuer || accountName)}:${encodeURIComponent(accountName)}`;
  const issuerParam = issuer ? `&issuer=${encodeURIComponent(issuer)}` : "";
  return `otpauth://totp/${label}?secret=${secret}&period=30&digits=6&algorithm=SHA1${issuerParam}`;
};
